1:/**
2: * RFC-4180 CSV writer used by both export routes (issues and the audit log).
3: *
4: * The rules that matter: fields containing a comma, a double quote or a line
5: * break are wrapped in double quotes and every embedded quote is doubled;
6: * rows are separated by CRLF; column order comes from the caller, never from
7: * object key order.
8: */
9:
10:const NEEDS_QUOTING = /[",\r\n]/;
11:
12:export function escapeCsvValue(value: string | number | boolean | null): string {
13:  if (value === null) return "";
14:  const text = String(value);
15:  if (!NEEDS_QUOTING.test(text)) return text;
16:  return `"${text.replace(/"/g, '""')}"`;
17:}
18:
19:/**
20: * Serialises `rows` using `columns` as both the header line and the field
21: * order. A column missing from a row is written as an empty field.
22: */
23:export function toCsv(
24:  rows: readonly Readonly<Record<string, string | number | boolean | null>>[],
25:  columns: readonly string[],
26:): string {
27:  const lines: string[] = [columns.map(escapeCsvValue).join(",")];
28:
29:  for (const row of rows) {
30:    lines.push(
31:      columns
32:        .map((column) => escapeCsvValue(row[column] ?? null))
33:        .join(","),
34:    );
35:  }
36:
37:  return lines.join("\r\n");
38:}
39:
40:/** The headers an export Route Handler returns alongside the CSV body. */
41:export function csvResponseHeaders(
42:  filename: string,
43:): Readonly<Record<string, string>> {
44:  const safe = filename.replace(/[^A-Za-z0-9._-]/g, "-");
45:  return {
46:    "Content-Type": "text/csv; charset=utf-8",
47:    "Content-Disposition": `attachment; filename="${safe}"`,
48:    "Cache-Control": "no-store",
49:  };
50:}

