>(input: T): T {
  const since = input.since === undefined ? undefined : toIsoTimestamp(input.since);
  const until = input.until === undefined ? undefined : toIsoTimestamp(input.until);

  if (since !== undefined && until !== undefined && until < since) {
    throw new Error("until must not be earlier than since");
  }

  return { ...input, since, until };
}

